tool_and_message_events.command:
/bin/bash -lc 'TMPDIR="$PWD" node --input-type=module - <<'"'NODE'
import { readFile } from 'node:fs/promises';
let runner = await readFile('visit.mjs', 'utf8');
runner = runner.replace('const args = JSON.parse(process.argv[2] ?? \"[]\")', 'const args = [{op:\"wait\",ms:300},{op:\"click\",target:\"text=Toggle schedule\"},{op:\"wait\",ms:900}]');
const probe = () => {
  const original = document.startViewTransition;
  window.animationTrace = [];
  document.startViewTransition = function (...args) {
    const transition = original.apply(this, args);
    const record = {};
    window.animationTrace.push(record);
    transition.ready.then(() => {
      record.ready = true;
      record.animations = document.documentElement.getAnimations({subtree:true})
        .filter(animation => animation.effect?.pseudoElement?.startsWith('::view-transition'))
        .map(animation => ({
          pseudo: animation.effect.pseudoElement,
          duration: animation.effect.getComputedTiming().duration,
          playState: animation.playState
        }));
      record.panelName = getComputedStyle(document.querySelector('main p')).viewTransitionName;
    }).catch(error => { record.readyError = String(error); });
    transition.finished.then(() => { record.finished = true; }).catch(error => { record.finishedError = String(error); });
    return transition;
  };
};
runner = runner.replace('  const route=', '  await request(\"Page.addScriptToEvaluateOnNewDocument\", {source: ' + JSON.stringify('(' + probe.toString() + ')()') + '});\\n  const route=');
runner = runner.replace('return {events,heading:', 'return {events,animationTrace:window.animationTrace,heading:');
await import('data:text/javascript;base64,' + Buffer.from(runner).toString('base64'));
NODE"

